function UINightCatITowerDialog:OnShow()
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if KCookie.Get("IsNightCatITowerEntry") == "1" then
            CS.Engine.Lib.KCookie.Set("IsNightCatITowerEntry", nil)
            CfUtils.PlayAnimator(self.Root, "Go")
        else
            CfUtils.PlayAnimator(self.Root, "Default")
        end

        local lastId = KCookie.Get("NightCatLastTowerQuestId")
        if checkNumber(lastId) > 0 then
            local vo = QuestConfMgr:GetInstance():GetQuestVoById(lastId)
            local activityVo = QuestConfMgr:GetInstance():GetNightCatActivityVo(self._activityId)

            --最大 不播
            if checkNumber(vo.storey) == checkNumber(activityVo.layers) then
                return
            end

            KCookie.Set("NightCatLastTowerQuestId", 0)
            self._co = cs_coroutine.start(function()
                UIRaycastBlocker:AddCondition("UINightCatITowerDialog")
                --coroutine.yield(CS.UnityEngine.WaitForSeconds(0.33))

                --local ani = self.Root.transform:GetComponent(typeof(Animator))
                --ani:SetBool("Complete", true)
                --CfUtils.PlayAnimator(self.Root, "Complete")

                local monstVo = QuestConfMgr:GetInstance():GetMonsterData(lastId)
                local node = self.MiddleGroup.transform:Find("ImgBg/BossMask/BossDrawingNodeOlde/BossDrawingNode"):GetComponent(DrawingNode)
                node:Execute(checkNumber(monstVo.skinId)) 

                self:InitData()
                monstVo = QuestConfMgr:GetInstance():GetMonsterData(self._curQuestId)
                node = self.MiddleGroup.transform:Find("ImgBg/BossMask/BossDrawingNode"):GetComponent(DrawingNode)
                node:Execute(checkNumber(monstVo.skinId)) 

                CfUtils.PlayAnimator(self.Root, "Switch")

                coroutine.yield(CS.UnityEngine.WaitForSeconds(0.33))

                self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
                self:FillSelf()

                coroutine.yield(CS.UnityEngine.WaitForSeconds(0.783))
                UIRaycastBlocker:RemoveCondition("UINightCatITowerDialog")
            end)
        end
    end))
    return coWait
end

function UINightCatITowerDialog:OnBattleLoadedOverHandler()
    CfUtils.StartCoroutineWithBlocker(function()
        xTry(function()
            local nowQuestId = checkNumber(self._curQuestId)
            self._curQuestId = checkNumber(self._curQuestId) - 1
            self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
            if isNull(self._curQuestVo) then
                goto start
            end
            self:FillSelf()

            cs_coroutine.yield_return(WaitForSeconds(0.8))
            CfUtils.PlayAnimator(self.Root, "Switch")
            cs_coroutine.yield_return(WaitForSeconds(0.5))

            ::start::

            self._curQuestId = nowQuestId
            self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
            self:FillSelf()
        end)
    end)
end

function UINightCatITowerDialog:Awake()
    if isNull(self._behaviourAction) then
        self._behaviourAction = CfUtils.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
        self._behaviourAction.UpdateAction = function()
            self:OnUpdate()
        end
    end

    self.events[Constants.EventNames.ExitBattleLoadOver] = Events.AddListener(Constants.EventNames.ExitBattleLoadOver, Bind(self, self.OnBattleLoadedOverHandler))

    CfUtils.SetActive(self.BtnEasyWay, false)
    ActivityNightCatMgr:PlayBGM()

    ---@type ActivityNightCatComponent
    self._nightCatComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityNightCatComponent)
    self.events[Constants.EventNames.ActivityNightCatResetRecover] = Events.AddListener(Constants.EventNames.ActivityNightCatResetRecover, Bind(self, self.FillResetInfo))
    SetButtonAction(self.BtnEasyWay, Bind(self, self.OnBtnEasyWay))
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnReward))
    SetButtonAction(self.BtnBuff, Bind(self, self.OnBtnBuff))
    SetButtonAction(self.BtnFight, Bind(self, self.OnBtnFight))
    SetButtonAction(self.BtnSet, Bind(self, self.OnBtnRefresh))
    SetButtonAction(self.ImgTime, function()
        UICommonUtils.ShowAttributeTips(self.ImgTime, {
            nightCat = true,
            name = localize("每次重置均会延长关卡的重置时间。"),
            descr = localize("第1~3次：15分钟\n第4~6次：30分钟\n第7~9次：1小时\n第10~12次：2小时\n第13次及以上：8小时\n每日5点将会重置累计次数。"),
        })
    end)

    local argument = self.controller.Argument.parameters
    if argument then
        self._activityId = checkNumber(argument.activityId)  

        self.Content.transform.offsetMin = argument.offsetMin
        self.Content.transform.offsetMax = argument.offsetMax
    end
    self._activityId = activityNightCatComponent:GetScheduleId()

    self:InitData()
    self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
    if not self._curQuestVo then
        return
    end

    self:FillSelf()
end

function UINightCatITowerDialog:OnUpdate()
    if self._homeDojo and self._homeDojo.nextHpSeconds >= 0 and self._homeDojo.climbingResetNum < self._homeDojo.limit then
        CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(self._homeDojo.nextHpSeconds))
    end
end

function UINightCatITowerDialog:InitData()
    --self._nightCatComponent:StartTimeDown()
    local id = comp:GetCurPassTowerId()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
    if not vo then
        local t = CfUtils.GetIdGroupData(AutoIds.IdSetting2736, self._activityId)
        self._curQuestId = t[1]
        return
    end

    --通关了
    if checkNumber(vo.nextLevel) == 0 then
        self._curQuestId = id
    else
        self._curQuestId = vo.nextLevel
    end

    local lastId = KCookie.Get("NightCatLastTowerQuestId")
    if checkNumber(lastId) > 0 then
        self._curQuestId = lastId
    end
end

function UINightCatITowerDialog:FillSelf()
    self:FillBossInfo()
    self:FillRewards()

    local num = checkNumber(self._curQuestVo.storey)
    CfUtils.SetActive(self.ImgNumber2, num >= 10)
    CfUtils.SetActive(self.ImgNumber22, num >= 10)

    CfUtils.SetActive(self.ImgNumber1, num >= 100)
    CfUtils.SetActive(self.ImgNumber11, num >= 100)

    CfUtils.SetUISwitchImage(self.ImgNumber3, num % 10 + 1)
    CfUtils.SetUISwitchImage(self.ImgNumber33, num % 10 + 1)

    local num1 = math.floor(num / 10)
    CfUtils.SetUISwitchImage(self.ImgNumber2, num1 % 10 + 1)
    CfUtils.SetUISwitchImage(self.ImgNumber22, num1 % 10 + 1)

    num1 = math.floor(num1 / 10)
    CfUtils.SetUISwitchImage(self.ImgNumber1, num1 % 10 + 1)
    CfUtils.SetUISwitchImage(self.ImgNumber11, num1 % 10 + 1)

    local isPassAll = QuestConfMgr:GetInstance():IsNightCatPassAll(self._activityId)
    self.ImgNumber11.transform:GetComponent(UIGrayGraphics):MarkGray(isPassAll)
    self.ImgNumber22.transform:GetComponent(UIGrayGraphics):MarkGray(isPassAll)
    self.ImgNumber33.transform:GetComponent(UIGrayGraphics):MarkGray(isPassAll)
    self.MiddleGroup.transform:Find("ImgBg/ImgBg") :GetComponent(UIGrayGraphics):MarkGray(isPassAll)

    local isFinish = false
    local vo = QuestConfMgr:GetInstance():GetNightCatActivityVo(self._activityId)
    if vo then
        local maxTowerId = comp:GetMaxPassTowerId()
        if maxTowerId == 0 then
            CfUtils.FillText(self.TxtNumber, "0/"..vo.layers)
        else
            local questVo = QuestConfMgr:GetInstance():GetQuestVoById(maxTowerId)
            CfUtils.FillText(self.TxtNumber, (checkNumber(questVo.storey)).."/"..vo.layers)
        end

        local curId = comp:GetCurPassTowerId()
        local curVo = QuestConfMgr:GetInstance():GetQuestVoById(curId)
        if curVo then
            isFinish = (checkNumber(curVo.storey) == checkNumber(vo.layers))
        end
    end

    CfUtils.SetActive(self.ClearanceNode, isFinish)
    self:FillResetInfo()
    self:RefreshBtnEasyWay()
end

function UINightCatITowerDialog:OnBtnEasyWay()
    if isNull(self.targetLevelId) then
        return
    end
    comp:FastClimbingTowerReq(comp:GetActivityUuId(), function()
        comp:UpdateCurTowerQuestId(self.targetLevelId)
        self:OnShow()
    end)
end

function UINightCatITowerDialog:RefreshBtnEasyWay()
    ---@TODO
    CfUtils.SetActive(self.BtnEasyWay, false)
    local maxId = comp:GetMaxPassTowerId()

    self.refLevel = 5

    --- 历史最高层数如果没超过5层就不显示
    ---@type NightCatTowerQuestVo
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(maxId)
    if isNull(vo) then
        return
    end
    local targetLevel = vo.storey - self.refLevel
    if targetLevel <= 0 then
        return
    end
    self.targetLevelId = maxId - self.refLevel

    --- 当前层数如果超过目标层数则不显示
    local curPassId = comp:GetCurPassTowerId()
    if curPassId == 0 then
        local allVo = CfUtils.GetCf(AutoIds.IdSetting2736, "NightCatTowerQuestVo", true)
        vo = allVo[1]
    else
        vo = QuestConfMgr:GetInstance():GetQuestVoById(curPassId)
    end

    if vo.storey >= targetLevel then
        return
    end

    CfUtils.SetActive(self.BtnEasyWay, true)
end

