function UINightCatITowerDialog:FillResetInfo()
    self._homeDojo = ActivityNightCatMgr:GetNightCatHomeDojo()
    CfUtils.FillText(self.TxtTime, localize("剩余重置次数：<color=#ff4777>_count1_</color>/_count2_", {_count1_=self._homeDojo.climbingResetNum, _count2_=self._homeDojo.limit}))

    local isHaveResetNum = self._homeDojo.climbingResetNum > 0
    --没次数了
    if not isHaveResetNum or comp:GetCurPassTowerId() == 0 then
        --CfUtils.SetActive(self.BtnSet.transform:Find("TimeGroup"), false)
        self.BtnSet.transform:Find("ImgTxtBg").transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(true)
        return
    end

    CfUtils.SetActive(self.BtnSet.transform:Find("TxtFight"), isHaveResetNum)

    self.BtnSet.transform:Find("ImgTxtBg").transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(not isHaveResetNum)
