    --    self:StartTimeDown()
    --end
end

--开始倒计时
function UINightCatITowerDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local time = comp:GetClimbingResetTtl()
        if checkNumber(time) <= 0 then
            self:FillResetInfo()
        else
            CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(time))
        end
    end, CountDownTime, false, true)
end

function UINightCatITowerDialog:FillBossInfo()
    local monstVo = QuestConfMgr:GetInstance():GetMonsterData(self._curQuestVo.id)

    if not monstVo then
        return
    end 
    self.BossDrawingNode:Execute(checkNumber(monstVo.skinId))    
    CfUtils.SetActive(self.MiddleGroup.transform:Find("ImgBg/BossMask"), true)
    local node = self.MiddleGroup.transform:Find("ImgBg/BossMask/BossDrawingNode"):GetComponent(DrawingNode)
    node:Execute(checkNumber(monstVo.skinId)) 

    node = self.MiddleGroup.transform:Find("ImgBg/BossMask/BossDrawingNodeOlde/BossDrawingNode"):GetComponent(DrawingNode)
    node:Execute(checkNumber(monstVo.skinId)) 
end

function UINightCatITowerDialog:FillRewards()
    local t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curQuestId)
    if not t then 
        return
    end

    for i = 1, self.RewardList.childCount do
        local go = self.RewardList:GetChild(i - 1)
        if go then
            CfUtils.SetActive(go, false)
        end
    end

    for k, v in pairs(t) do
        local go = self.RewardList.transform:Find("Good"..k)
        if not go then
            go = CfUtils.InstantiateGo(self.Good, self.RewardList)
            go.name = "Good"..k
        end

        self:FillReward(go, v)
    end
end

function UINightCatITowerDialog:FillReward(go, data)
    if not go or not data then
        return
    end
    CfUtils.RefeshGoodGo(go.transform:Find("GoodNode"), data.id, data.num, 0.65, nil, function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.id)
        if vo then
            GameUtils.ShowCommonTipsBoard(go.transform:Find("TipRoot"), vo.name, nil, vo.quality, data.id, false,nil)
        end
    end)
    CfUtils.FillRewardGoTitle(go.transform:Find("GoodNode"), data)
    CfUtils.SetActive(go, true)

    --必定掉落不灰
    local type = checkNumber(data.type)
    if type == Constants.TeamShowRewardType.RegularType then
        return
    end

    local maxTowerId = comp:GetMaxPassTowerId()
    local maxVo = QuestConfMgr:GetInstance():GetQuestVoById(maxTowerId)
    if maxVo then
        local scr = CfUtils.GetLuaScr(go.transform:Find("GoodNode"), "Game.Behaviours.GoodNodeMB")
        if scr then
            scr:SetSanXingGainShow(checkNumber(maxVo.storey) >= checkNumber(self._curQuestVo.storey))
        end  
    end
end

function UINightCatITowerDialog:OnBtnRefresh()
    local isOpne = comp:IsOpen()
    if not isOpne then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local questId = comp:GetCurPassTowerId()
    if isNull(self._homeDojo) or questId == 0 then
        return
    end
    local isHaveResetNum = self._homeDojo.climbingResetNum > 0
    if not isHaveResetNum then
        GameUtils.Toast(localize("重置次数不足"))
        return
    end

    GameUtils.SecondConfirm(localize("是否要重置"), function()
        comp:ActivityNightCatResetReq(function(jsonData)
            self._co = cs_coroutine.start(function()
                UIRaycastBlocker:AddCondition("UINightCatITowerDialog")

                self._nightCatComponent:RefreshResetInfo(jsonData)
                self._nightCatComponent:StartTimeDown()
                CfUtils.PlayAnimator(self.Root, "Switch")
                --local ani = self.Root.transform:GetComponent(typeof(Animator))
                --ani:SetBool("Switch", true)
                coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))

                self:InitData()
                self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
                self:FillSelf()
                coroutine.yield(CS.UnityEngine.WaitForSeconds(1.083 - 0.2))
                UIRaycastBlocker:RemoveCondition("UINightCatITowerDialog")
            end)
        end)
    end, function()
        
    end)
end

function UINightCatITowerDialog:OnBtnFight()
    local isOpne = comp:IsOpen()
    if not isOpne then
        GameUtils.Toast(localize("活动已结束"))
        return
    end

    local isPassAll = QuestConfMgr:GetInstance():IsPassAllNightCatQuestTowerQuest()
    if isPassAll then
        GameUtils.Toast(localize("已通关全部"))
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curQuestId, activityUuid = comp:GetActivityUuId() } }, {
        { id = Constants.UITypeIds.UINightCatITowerDialog },
    })
end

